import React, { useState, useEffect } from 'react';
import Login from './components/Login';
import Sidebar from './components/Sidebar';
import DailyTasks from './components/DailyTasks';
import CalendarView from './components/CalendarView';
import Templates from './components/Templates';
import api from './api';

function App() {
  const [user, setUser] = useState(null);
  const [currentView, setCurrentView] = useState('daily');
  const [sidebarOpen, setSidebarOpen] = useState(false);

  useEffect(() => {
    // Check if user is already logged in
    const token = localStorage.getItem('token');
    if (token) {
      const storedUser = localStorage.getItem('user');
      if (storedUser) {
        setUser(JSON.parse(storedUser));
      }
    }
  }, []);

  const handleLogin = (userData) => {
    setUser(userData);
    localStorage.setItem('user', JSON.stringify(userData));
  };

  const handleLogout = () => {
    api.logout();
    setUser(null);
    localStorage.removeItem('user');
    setCurrentView('daily');
  };

  const toggleSidebar = () => {
    setSidebarOpen(!sidebarOpen);
  };

  const closeSidebar = () => {
    setSidebarOpen(false);
  };

  if (!user) {
    return <Login onLogin={handleLogin} />;
  }

  const renderView = () => {
    switch (currentView) {
      case 'daily':
      case 'weekly':
      case 'monthly':
        return <DailyTasks initialView={currentView} />;
      case 'calendar':
        return user.role === 'admin' ? <CalendarView /> : <DailyTasks initialView="daily" />;
      case 'templates':
        return user.role === 'admin' ? <Templates /> : <DailyTasks initialView="daily" />;
      default:
        return <DailyTasks initialView="daily" />;
    }
  };

  return (
    <div className="app">
      <button className="hamburger" onClick={toggleSidebar}>
        ☰
      </button>

      {sidebarOpen && <div className="sidebar-overlay visible" onClick={closeSidebar}></div>}

      <Sidebar
        user={user}
        currentView={currentView}
        setCurrentView={(view) => {
          setCurrentView(view);
          closeSidebar();
        }}
        onLogout={handleLogout}
        isOpen={sidebarOpen}
      />

      <div className={`main-content ${sidebarOpen ? 'sidebar-visible' : 'sidebar-hidden'}`}>
        {renderView()}
      </div>
    </div>
  );
}

export default App;
